def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    return ''

def hasact(adm, prefix, target, dest):
    for a in adm or []:
        s = text(a)
        if s.startswith(prefix) and (not target or target in s) and (not dest or dest in s):
            return True
    return False

def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', ''))
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transform_done'] = True
    else:
        act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
        if act.startswith(verb + ' ') and target in act:
            nb['transform_done'] = True
    inv = text(getv(ctx, 'world.inventory', ''))
    carrying = bool(target and target in inv and 'nothing' not in inv and 'not carrying' not in inv)
    wrong = bool(inv and target and target not in inv and 'nothing' not in inv and 'not carrying' not in inv)
    pc = getv(ctx, 'world.placed_count', nb.get('placed_count', 0))
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    if verb and target and act.startswith('put ') and target in act and dest and dest in act and (not nb.get('transform_done') or not nb.get('stage')):
        nb['stage'] = 'wrong_transform'
    if wrong:
        nb['stage'] = 'wrong_inventory'
    elif carrying and verb and not nb.get('transform_done'):
        nb['stage'] = 'transform'
    elif carrying and dest and hasact(ctx.get('admissible') or [], 'put ', target, dest):
        nb['stage'] = 'put_target'
    elif carrying:
        nb['stage'] = 'go_destination'
    elif target and hasact(ctx.get('admissible') or [], 'take ', target, ''):
        nb['stage'] = 'take_target'
    else:
        nb['stage'] = 'find_target'
    return None

