def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', ''))
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    stage = nb.get('stage', '')
    msg = ''
    if stage == 'wrong_transform':
        msg = 'That was the wrong transform or destination for this task. Recover by taking the target back if needed, using the required ' + verb + ' action, then placing it at the requested ' + dest + '.'
    elif stage == 'wrong_inventory':
        msg = 'You are carrying a non-target item. Do not place it as the goal; put it back or ignore it, then search for the ' + target + '.'
    elif stage == 'transform' and verb and target:
        msg = 'You are carrying the ' + target + '. Before any put action, use the admissible ' + verb + ' action on it; do not substitute a different transform.'
    elif stage == 'put_target' and target and dest:
        msg = 'You are at the goal with the ' + target + '. Use the admissible put action to place it in/on the ' + dest + ', not a different receptacle.'
    elif stage == 'go_destination' and target and dest and verb and not nb.get('transform_done'):
        msg = 'Carry the ' + target + ' to a ' + verb + ' station first, then return to the ' + dest + ' for placement.'
    elif stage == 'take_target' and target:
        msg = 'A ' + target + ' is available here. Take it instead of continuing to search unrelated containers.'
    elif stage == 'find_target' and target and (getv(ctx, 'predicates.same_action_repeated', False) or getv(ctx, 'predicates.same_observation_repeated', False) or getv(ctx, 'predicates.remaining_steps_low', False)):
        msg = 'Search unopened or unvisited containers for the ' + target + '; avoid repeating the same examine, inventory, or go action.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

